// Medical Terminology Practice Test 1. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items: building and decoding multi-part terms and
// telling apart word parts that look or sound alike.
import {q, mix} from './q.js';
const EHR='Ehrlich, Medical Terminology for Health Professions', STAN='Stanhope & Turnbull, Introduction to Medical Terminology', TAB='Taber’s Cyclopedic Medical Dictionary';
const WP='Roots, Prefixes, Suffixes, and Combining Forms', BODY='Overview of Body', SKEL='Skeletal', MUS='Muscular', RESP='Respiratory', DIG='Digestive', CV='Cardiovascular & Lymphatic', NERV='Nervous/Special Senses', ENDO='Endocrine', REPRO='Reproductive', INTEG='Integumentary', URIN='Urinary';

export default {
 id:'medical-terminology-1',
 event:'Medical Terminology',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Ehrlich’s Medical Terminology for Health Professions, Stanhope & Turnbull, and Taber’s Cyclopedic Medical Dictionary',
 plan:[{area:WP,weight:45},{area:BODY,weight:5},{area:SKEL,weight:5},{area:MUS,weight:5},{area:RESP,weight:5},{area:DIG,weight:5},{area:CV,weight:5},{area:NERV,weight:5},{area:ENDO,weight:5},{area:REPRO,weight:5},{area:INTEG,weight:5},{area:URIN,weight:5}],
 questions:mix([
  q(WP,'Which term means “surgical fixation of a kidney”?','Nephropexy',['Nephrorrhaphy','Nephrolysis','Nephroptosis'],'B','Nephr/o means kidney and -pexy means surgical fixation. Nephrorrhaphy is suturing of the kidney, nephrolysis is freeing the kidney from adhesions, and nephroptosis is a drooping (prolapsed) kidney.',EHR),
  q(WP,'Which suffix means “rupture”?','-rrhexis',['-rrhaphy','-rrhagia','-rrhea'],'D','The four “rrh” suffixes are easy to confuse: -rrhexis means rupture, -rrhaphy means suturing, -rrhagia means bleeding or bursting forth of blood, and -rrhea means flow or discharge.',EHR),
  q(WP,'A patient after a stroke has dysphasia. What does this term mean?','Difficulty speaking',['Difficulty swallowing','Absence of the voice','Difficulty breathing'],'A','-phasia refers to speech, so dysphasia is difficulty speaking. Dysphagia (-phagia, eating or swallowing) is difficulty swallowing; aphonia is loss of voice; dyspnea is difficulty breathing.',EHR),
  q(WP,'Which prefix means “one and one-half”?','Sesqui-',['Hemi-','Bi-','Semi-'],'C','Sesqui- means one and one-half. Hemi- and semi- both mean half, and bi- means two.',TAB),
  q(WP,'Which combining form refers to the last part of the small intestine rather than the hip bone?','ile/o',['ili/o','ischi/o','isch/o'],'C','Ile/o (with an e) is the ileum, the last part of the small intestine. Ili/o (with an i) is the ilium, part of the hip bone. Ischi/o is the ischium, and isch/o means to hold back, as in ischemia.',EHR),
  q(WP,'The combining form myel/o can refer to which two structures?','The spinal cord and the bone marrow',['The muscles and the tendons','The myelin sheath and the meninges','The bone marrow and the lymph nodes'],'A','Myel/o means both bone marrow (myeloma) and spinal cord (myelitis, myelogram). Context decides the meaning. My/o means muscle.',EHR),
  q(WP,'In the term bronchiectasis, what does the suffix -ectasis mean?','Dilation or stretching',['Narrowing or tightening','Drooping or sagging','Abnormal softening'],'D','-ectasis means dilation or stretching, so bronchiectasis is a permanent widening of the bronchi. Narrowing is -stenosis, drooping is -ptosis, and softening is -malacia.',EHR),
  q(WP,'Which term describes inflammation of the inner lining of the heart?','Endocarditis',['Pericarditis','Myocarditis','Epicarditis'],'B','Endo- means within, so the endocardium is the inner lining of the heart. Peri- (around) refers to the sac around the heart, myo- to the heart muscle, and epi- to the outer layer.',STAN),
  q(WP,'Cholecystectomy is the surgical removal of which structure?','Gallbladder',['Urinary bladder','Common bile duct','Pancreatic duct'],'D','Chol/e means bile or gall, cyst/o means bladder or sac, and -ectomy means surgical removal. Together they describe removal of the gallbladder. Choledoch/o refers to the common bile duct.',EHR),
  q(WP,'In the term hematopoiesis, what does -poiesis mean?','Formation or production',['Destruction or breakdown','Deficiency or decrease','Flow or movement'],'B','-poiesis means formation, so hematopoiesis is the formation of blood cells. Destruction is -lysis, a deficiency is -penia, and flow is -rrhea.',EHR),
  q(WP,'Which term means “crushing of a stone” and names a procedure used to break up kidney stones?','Lithotripsy',['Lithotomy','Lithiasis','Litholysis'],'C','-tripsy means crushing. A lithotomy is an incision to remove a stone, lithiasis is the presence of stones, and litholysis is dissolving a stone.',EHR),
  q(WP,'Which term means abnormally slow breathing?','Bradypnea',['Tachypnea','Dyspnea','Orthopnea'],'A','Brady- means slow and -pnea means breathing. Tachypnea is rapid breathing, dyspnea is difficult breathing, and orthopnea is difficulty breathing except when sitting or standing upright.',STAN),
  q(WP,'Which term means abnormal development or growth of cells, often a precancerous change?','Dysplasia',['Dystrophy','Dyskinesia','Dystocia'],'A','-plasia means development or formation. Dystrophy is degeneration from poor nourishment, dyskinesia is difficulty with movement, and dystocia is difficult labor.',EHR),
  q(WP,'Which suffix means “surgical creation of an artificial opening”?','-stomy',['-tomy','-ectomy','-centesis'],'C','-stomy means surgically creating an opening, as in a colostomy. -tomy is a cutting or incision, -ectomy is removal, and -centesis is a surgical puncture to remove fluid.',EHR),
  q(WP,'What is arthrocentesis?','Puncture of a joint to remove fluid',['Surgical fusion of a joint','Visual examination of a joint','Surgical repair of a joint'],'B','Arthr/o means joint and -centesis means surgical puncture to remove fluid. Fusion is arthrodesis, visual examination is arthroscopy, and surgical repair is arthroplasty.',EHR),
  q(WP,'The prefixes circum- and peri- share which meaning?','Around',['Through','Between','Beneath'],'D','Circum- and peri- both mean around, as in circumcision and pericardium. Through is dia- or trans-, between is inter-, and beneath is sub- or infra-.',STAN),
  q(WP,'A patient has xeroderma. The combining form xer/o means:','Dry',['Yellow','White','Red'],'C','Xer/o means dry, so xeroderma is excessively dry skin. Yellow is xanth/o, white is leuk/o, and red is erythr/o.',EHR),
  q(WP,'Which combining form means “straight”?','orth/o',['ankyl/o','kyph/o','lord/o'],'B','Orth/o means straight, as in orthodontics and orthopnea. Ankyl/o means crooked, bent or stiff; kyph/o means hump; and lord/o means curve or swayback.',EHR),
  q(WP,'In the term cholelithiasis, the suffix -iasis indicates:','An abnormal condition or presence of',['Inflammation of','Surgical repair of','Enlargement of'],'D','-iasis means an abnormal condition, often the presence of something. Cholelithiasis is the presence of gallstones. Inflammation is -itis, repair is -plasty, and enlargement is -megaly.',EHR),
  q(WP,'Which term means enlargement of both the liver and the spleen?','Hepatosplenomegaly',['Splenohepatomalacia','Hepatosplenitis','Hepatosplenoptosis'],'A','Hepat/o (liver) + splen/o (spleen) + -megaly (enlargement) = hepatosplenomegaly. -malacia means softening, -itis means inflammation, and -ptosis means drooping.',EHR),
  q(WP,'What does erythrocytopenia mean?','A deficiency of red blood cells',['An excess of red blood cells','A deficiency of white blood cells','Destruction of platelets'],'D','Erythr/o (red) + cyt/o (cell) + -penia (deficiency) = a deficiency of red blood cells. An excess would be erythrocytosis, and a white cell deficiency is leukopenia.',STAN),
  q(WP,'In the term hemolysis, the suffix -lysis means:','Breakdown, destruction or separation',['Formation or production','Stopping or controlling','Narrowing or tightening'],'A','-lysis means breakdown, destruction or separation, so hemolysis is the breakdown of red blood cells. Formation is -poiesis, stopping is -stasis, and narrowing is -stenosis.',EHR),
  q(WP,'Which term means “pertaining to the area between the ribs”?','Intercostal',['Infracostal','Subcostal','Supracostal'],'C','Inter- means between and cost/o means rib. Infra- and sub- both mean below, and supra- means above.',STAN),
  q(BODY,'Which plane divides the body into anterior (front) and posterior (back) portions?','Frontal (coronal) plane',['Sagittal plane','Transverse plane','Midsagittal plane'],'B','The frontal or coronal plane is a vertical plane that separates front from back. Sagittal planes separate right from left, and the transverse plane separates upper from lower.',EHR),
  q(BODY,'Which abdominopelvic region lies directly superior to the umbilical region?','Epigastric region',['Hypogastric region','Right hypochondriac region','Left lumbar region'],'A','Epi- means above and gastr/o means stomach; the epigastric region sits above the umbilical region. The hypogastric region is below it, the hypochondriac regions are below the ribs on each side, and the lumbar regions are beside it.',EHR),
  q(SKEL,'What is osteomalacia?','Abnormal softening of the bones',['Abnormal porousness of the bones','Inflammation of bone and bone marrow','A benign tumor of bone and cartilage'],'B','Oste/o (bone) + -malacia (softening) = osteomalacia, often from vitamin D deficiency. Porous bones are osteoporosis, bone and marrow inflammation is osteomyelitis, and a benign bone-and-cartilage tumor is an osteochondroma.',EHR),
  q(SKEL,'Which term describes an abnormal lateral (sideways) curvature of the spine?','Scoliosis',['Kyphosis','Lordosis','Spondylosis'],'D','Scoli/o means curved or bent sideways. Kyphosis is an outward hump of the upper back, lordosis is an inward curve of the lower back, and spondylosis is degeneration of the vertebrae.',EHR),
  q(SKEL,'What is arthrodesis?','Surgical fusion of a joint',['Surgical repair of a joint','Surgical incision of a joint','Dislocation of a joint'],'C','-desis means binding or fusion, so arthrodesis stiffens a joint by fusing the bones. Repair is arthroplasty, incision is arthrotomy, and dislocation is luxation.',EHR),
  q(MUS,'The term myasthenia gravis contains the suffix -asthenia. What does it mean?','Weakness or lack of strength',['Tension or tone','Paralysis','Wasting'],'B','-asthenia means weakness. Myasthenia gravis is a disorder causing muscle weakness. Tone is -tonia, paralysis is -plegia, and wasting is atrophy.',EHR),
  q(MUS,'Which term describes moving a limb away from the midline of the body?','Abduction',['Adduction','Circumduction','Supination'],'C','Ab- means away from, so abduction moves a limb away from the midline. Ad- means toward, circumduction is circular movement, and supination turns the palm upward.',EHR),
  q(RESP,'A patient is coughing up blood-tinged sputum. Which term describes this?','Hemoptysis',['Hematemesis','Epistaxis','Hemothorax'],'A','-ptysis means spitting, so hemoptysis is coughing up blood from the respiratory tract. Hematemesis is vomiting blood, epistaxis is a nosebleed, and hemothorax is blood in the pleural cavity.',EHR),
  q(RESP,'What is atelectasis?','Incomplete expansion or collapse of part of a lung',['Inflammation of the pleura','Excess fluid in the pleural space','Permanent widening of the bronchi'],'D','Atel/o means incomplete or imperfect and -ectasis means expansion. Pleural inflammation is pleurisy, fluid in the pleural space is a pleural effusion, and widened bronchi is bronchiectasis.',EHR),
  q(RESP,'Which procedure uses a needle to remove fluid from the pleural space?','Thoracentesis',['Thoracotomy','Tracheostomy','Bronchoscopy'],'D','Thorac/o (chest) + -centesis (surgical puncture to remove fluid). A thoracotomy is an incision into the chest, a tracheostomy creates an opening in the trachea, and bronchoscopy is a visual exam of the bronchi.',EHR),
  q(DIG,'Which term means “pertaining to the cheek”?','Buccal',['Labial','Lingual','Gingival'],'C','Bucc/o means cheek, as in a buccal medication placed between cheek and gum. Labi/o means lip, lingu/o means tongue, and gingiv/o means gums.',EHR),
  q(DIG,'What is a choledocholithotomy?','An incision into the common bile duct to remove a stone',['Removal of the gallbladder to treat gallstones','Crushing of a gallstone with sound waves','Creating an opening between the bile duct and intestine'],'B','Choledoch/o (common bile duct) + lith/o (stone) + -tomy (incision). Gallbladder removal is a cholecystectomy, crushing is lithotripsy, and joining the duct to the intestine uses -stomy.',EHR),
  q(DIG,'A patient reports black, tarry stools. Which term describes this?','Melena',['Hematochezia','Steatorrhea','Hematemesis'],'A','Melena is black, tarry stool from digested blood, usually from the upper GI tract. Hematochezia is bright red blood in the stool, steatorrhea is fatty stool, and hematemesis is vomiting blood.',EHR),
  q(CV,'In atherosclerosis, the combining form ather/o refers to:','Fatty plaque',['Hardening','A blood clot','An artery'],'C','Ather/o means plaque or fatty substance, so atherosclerosis is hardening of arteries caused by fatty plaque. Scler/o means hardening, thromb/o means clot, and arteri/o means artery.',EHR),
  q(CV,'Which term describes a localized, balloon-like dilation of an artery wall?','Aneurysm',['Embolus','Thrombus','Stenosis'],'D','An aneurysm is a weakened, bulging section of an artery. An embolus is a traveling clot or mass, a thrombus is a clot attached to a vessel wall, and stenosis is narrowing.',EHR),
  q(CV,'What does lymphadenopathy mean?','Disease or enlargement of the lymph nodes',['Inflammation of the lymph vessels','Removal of a lymph node','Swelling caused by lymph fluid'],'A','Lymph/o + aden/o (gland) + -pathy (disease) refers to lymph node disease, often seen as swollen nodes. Inflamed vessels are lymphangitis, removal is lymphadenectomy, and lymph swelling is lymphedema.',EHR),
  q(NERV,'After a stroke, a patient has slight weakness on the right side of the body. Which term describes this?','Hemiparesis',['Hemiplegia','Paraplegia','Quadriplegia'],'B','-paresis means partial or slight paralysis, so hemiparesis is weakness of one side. Hemiplegia is complete paralysis of one side, paraplegia affects the lower body, and quadriplegia affects all four limbs.',EHR),
  q(NERV,'What is a myringotomy?','An incision into the eardrum',['Surgical repair of the middle ear bones','Removal of the mastoid process','A visual examination of the ear canal'],'A','Myring/o (like tympan/o) means eardrum, and -tomy means incision. It is often done to drain fluid and place ear tubes. Otoscopy is visual examination of the ear.',EHR),
  q(NERV,'The combining form blephar/o refers to which structure?','Eyelid',['Cornea','Iris','Tear gland'],'D','Blephar/o means eyelid, as in blepharoplasty. Kerat/o refers to the cornea, irid/o to the iris, and dacry/o or lacrim/o to tears.',EHR),
  q(ENDO,'A patient with uncontrolled diabetes reports excessive thirst. Which term describes this?','Polydipsia',['Polyuria','Polyphagia','Polycythemia'],'B','-dipsia means thirst. Polyuria is excessive urination, polyphagia is excessive hunger, and polycythemia is an abnormal increase in red blood cells.',EHR),
  q(ENDO,'Which condition is enlargement of the hands, feet and face caused by excess growth hormone in adulthood?','Acromegaly',['Gigantism','Myxedema','Exophthalmos'],'A','Acr/o means extremities and -megaly means enlargement. Excess growth hormone before the growth plates close causes gigantism instead. Myxedema is severe hypothyroidism, and exophthalmos is bulging eyes.',EHR),
  q(REPRO,'What is an oophorectomy?','Surgical removal of an ovary',['Surgical removal of a fallopian tube','Surgical removal of the uterus','Surgical removal of a testicle'],'D','Oophor/o means ovary. Removal of a fallopian tube is a salpingectomy, of the uterus a hysterectomy, and of a testicle an orchiectomy.',EHR),
  q(REPRO,'What is cryptorchidism?','A testicle that has not descended into the scrotum',['Inflammation of a testicle','A fluid-filled sac around a testicle','Absence of sperm in the semen'],'B','Crypt/o means hidden and orchid/o means testicle. Inflammation is orchitis, a fluid-filled sac is a hydrocele, and absence of sperm is azoospermia.',EHR),
  q(INTEG,'What is onychomycosis?','A fungal infection of the nail',['An ingrown nail','Inflammation of the skin around a nail','Separation of the nail from its bed'],'C','Onych/o (nail) + myc/o (fungus) + -osis (abnormal condition). An ingrown nail is onychocryptosis, inflamed skin around the nail is paronychia, and separation is onycholysis.',EHR),
  q(INTEG,'Which term describes an abnormally raised, thickened scar that grows beyond the original wound?','Keloid',['Callus','Cicatrix','Wheal'],'A','A keloid is an overgrowth of scar tissue. A callus is thickened skin from friction, a cicatrix is any normal scar, and a wheal is a smooth, raised, itchy swelling.',EHR),
  q(URIN,'Which term means frequent, excessive urination at night?','Nocturia',['Enuresis','Dysuria','Oliguria'],'C','Noct/i means night and -uria refers to urine. Enuresis is involuntary urination, often during sleep; dysuria is painful urination; and oliguria is scanty urine production.',EHR),
  q(URIN,'What is hydronephrosis?','Dilation of the renal pelvis caused by a backup of urine',['Inflammation of the kidney and renal pelvis','Excess protein in the urine','Drooping of a kidney'],'A','Hydr/o (water) + nephr/o (kidney) + -osis. A blockage keeps urine from draining, so the renal pelvis swells. Kidney and pelvis inflammation is pyelonephritis, excess protein is proteinuria, and drooping is nephroptosis.',EHR)
 ],11)
};
